import MenubarCheckbox from "../examples/menubar-checkbox";

const Example = () => <MenubarCheckbox />;

export default Example;

import MenubarExample from "../examples/menubar-demo";

const Example = () => (
  <div className="w-full max-w-2xl min-w-72 p-4">
    <MenubarExample />
  </div>
);

export default Example;

import {
  Menubar,
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarItem,
  MenubarList,
} from "@/registry/erbium/ui/menubar";

export const defaultProps = {
  align: "start",
  className: "",
  disabled: false,
  itemVariant: "default",
} satisfies {
  className: string;
  align: "start" | "center" | "end";
  itemVariant: "default" | "error";
  disabled: boolean;
};

export default function MenubarPlaygroundExample(
  args: {
    className: string;
    align: "start" | "center" | "end";
    itemVariant: "default" | "error";
    disabled: boolean;
  } = defaultProps,
) {
  return (
    <Menubar className={args.className}>
      <MenubarMenu>
        <MenubarTrigger disabled={args.disabled}>File</MenubarTrigger>
        <MenubarContent align={args.align}>
          <MenubarList>
            <MenubarItem variant={args.itemVariant}>New</MenubarItem>
            <MenubarItem>Open</MenubarItem>
          </MenubarList>
        </MenubarContent>
      </MenubarMenu>
    </Menubar>
  );
}

import MenubarRadio from "../examples/menubar-radio";

const Example = () => <MenubarRadio />;

export default Example;

import { useState } from "react";

import {
  Menubar,
  MenubarMenu,
  MenubarTrigger,
  MenubarContent,
  MenubarSearch,
  MenubarList,
  MenubarEmpty,
  MenubarGroup,
  MenubarLabel,
  MenubarItem,
} from "@/registry/erbium/ui/menubar";

export default function SearchableExample() {
  const [action, setAction] = useState("No action selected.");

  return (
    <div className="grid gap-related">
      <Menubar>
        <MenubarMenu searchable>
          <MenubarTrigger>Project</MenubarTrigger>
          <MenubarContent className="w-72">
            <MenubarSearch aria-label="Search project actions" />
            <MenubarEmpty>No project actions found.</MenubarEmpty>
            <MenubarList>
              <MenubarGroup>
                <MenubarLabel>Project</MenubarLabel>
                {["Open project", "Rename project", "Duplicate project", "Copy project link"].map(
                  (label) => (
                    <MenubarItem
                      key={label}
                      label={label}
                      onClick={() => {
                        setAction(label);
                      }}
                    >
                      {label}
                    </MenubarItem>
                  ),
                )}
              </MenubarGroup>

              <MenubarGroup>
                <MenubarLabel>Export</MenubarLabel>
                {["Export PDF", "Export Markdown", "Export CSV", "Download archive"].map(
                  (label) => (
                    <MenubarItem
                      key={label}
                      label={label}
                      onClick={() => {
                        setAction(label);
                      }}
                    >
                      {label}
                    </MenubarItem>
                  ),
                )}
              </MenubarGroup>
            </MenubarList>
          </MenubarContent>
        </MenubarMenu>
      </Menubar>
      <output className="text-caption text-muted-foreground">{action}</output>
    </div>
  );
}

import MenubarSubmenu from "../examples/menubar-submenu";

const Example = () => <MenubarSubmenu />;

export default Example;

import MenubarIcons from "../examples/menubar-icons";

const Example = () => <MenubarIcons />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);
